UPDATE com_cd_info SET COM_CD_NM = #{comCdNm}, COM_CD_EXPLN = #{comCdExpln},
       COM_CD_SEQ = #{comCdSeq}, COM_CD_USE_YN = #{comCdUseYn}, EXT1_CN = #{ext1Cn}, EXT2_CN = #{ext2Cn},
       MDFCN_DT = NOW(), MDFR_ID = #{mdfrId}
 WHERE COM_CD_GROUP_ID = #{comCdGroupId} AND COM_CD = #{comCd}
